import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer, UiOpenResult } from 'claude-code'

import { fitRows, moodOf, renderScene, withMarks, type Scene, type Style } from './scene'
import { textRows } from './text-rows'

const fill = atom({ plugin: 'forest', key: 'fill' } as const, 0)
const preview = atom({ plugin: 'forest', key: 'preview' } as const, null)
const hourOverride = atom({ plugin: 'forest', key: 'hour' } as const, null)
const seed = atom({ plugin: 'forest', key: 'seed' } as const, null)
const boost = atom({ plugin: 'forest', key: 'boost' } as const, 0)
const style = atom({ plugin: 'forest', key: 'style' } as const, 'ascii')
const baseline = atom({ plugin: 'forest', key: 'baseline' } as const, null)

const PANE = 'forest'

/** Seconds between animation steps unless `/forest speed` set another; kept across sessions. */
const DEFAULT_SPEED = 5

// The module's own variables: they start over on a reload, which is fine,
// since each is re-derived (the tick, the offset, the theme).
const local = {
  tick: 0,
  utcOffsetHours: null as number | null,
  theme: 'dark' as 'dark' | 'light',
  /** What each pane's Raster was last mounted at, so a blit matches it. */
  mounted: new Map<string, { columns: number; rows: number }>(),
  timer: null as Timer | null,
  /** The running `/forest set` time-lapse, if any. */
  sweep: null as Timer | null,
  /** The size the scene is laid out at; small height changes are fitted to it, not re-laid. */
  design: null as { columns: number; rows: number } | null,
  /** Where the pointer is over the pane, if it is; kept for hover features. */
  hover: null as { x: number; y: number } | null,
  /** Sparkles left by clicks, and the timer that fades them. */
  sparks: [] as { x: number; y: number; age: number }[],
  sparkTimer: null as Timer | null,
}

const SWEEP_FRAMES = 24
const SWEEP_MS = 125

const clamp01 = (n: number) => Math.max(0, Math.min(1, n))

/** The growth the scene shows: a preview if one is set, else live plus any boost. */
async function shownFill($: EngineInterface) {
  const forced = await read($, preview)
  return forced ?? clamp01((await read($, fill)) + (await read($, boost)))
}

/**
 * Plays the scene from its current growth to `target` as a time-lapse (the
 * preview stepping, clouds and fish hurrying), then keeps the target by
 * boosting the live fill, so real growth carries on from there.
 */
async function fastForward($: EngineInterface, target: number) {
  local.sweep?.cancel()
  const from = await shownFill($)
  let frame = 0
  local.sweep = $.clock.every(SWEEP_MS, async () => {
    frame += 1
    const t = frame / SWEEP_FRAMES
    const eased = t < 1 ? 1 - (1 - t) ** 3 : 1
    local.tick += 3
    if (frame < SWEEP_FRAMES) {
      await update($, preview, () => from + (target - from) * eased)
      return
    }
    local.sweep?.cancel()
    local.sweep = null
    const live = await read($, fill)
    await update($, boost, () => target - live)
    await update($, preview, () => null)
  })
}

const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

/** Standard padded base64 of the cells' little-endian bytes, as Raster takes them. */
function encode(cells: Uint32Array) {
  const bytes = new Uint8Array(cells.buffer, cells.byteOffset, cells.byteLength)
  const out: string[] = []
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i]!
    const b = bytes[i + 1]
    const c = bytes[i + 2]
    const n = (a << 16) | ((b ?? 0) << 8) | (c ?? 0)
    out.push(B64[n >> 18]! + B64[(n >> 12) & 63]! + (b === undefined ? "=" : B64[(n >> 6) & 63]!) + (c === undefined ? "=" : B64[n & 63]!))
  }
  return out.join("")
}

async function hourNow($: EngineInterface) {
  const forced = await read($, hourOverride)
  if (forced !== null) return forced
  const now = await $.clock.now()
  const offset = local.utcOffsetHours ?? -new Date(now).getTimezoneOffset() / 60
  return (((now / 3_600_000 + offset) % 24) + 24) % 24
}

/**
 * The scene for a pane of this size. It is laid out at a design size that
 * holds through small height changes (a prompt growing a line), and fitted to
 * the pane by cutting or repeating rows of quiet sky, so nothing jumps. A new
 * width, or a height far from the design's, lays it out afresh.
 */
async function sceneFor($: EngineInterface, columns: number, rows: number): Promise<Scene> {
  // a module variable, not state: a render hook may not write state
  let d = local.design
  if (!d || d.columns !== columns || rows < d.rows * 0.6 || rows > d.rows * 1.5) d = local.design = { columns, rows }
  const scene = renderScene({
    columns,
    rows: d.rows,
    fill: await shownFill($),
    tick: local.tick,
    hour: await hourNow($),
    theme: local.theme,
    seed: (await read($, seed)) ?? 7,
    style: await read($, style),
  })
  return withMarks(fitRows(scene, rows), local.sparks.map(p => ({ ...p, kind: 'sparkle' as const })))
}

/** Repaints the mounted Raster now, outside the animation step. */
async function repaint($: EngineInterface) {
  for (const [id, size] of local.mounted) {
    const scene = await sceneFor($, size.columns, size.rows)
    await $.ui.blit({ requestId: id, key: 'scene', cells: encode(scene.cells), ...size }).catch(() => null)
  }
}

/** What the pointer overlay posted: where the pointer is, and clicks, which leave a sparkle. */
async function onPointer($: EngineInterface, data: unknown) {
  const d = data as { kind?: string; x?: number; y?: number }
  if (typeof d.x !== 'number' || typeof d.y !== 'number') return
  const at = { x: d.x, y: d.y }
  local.hover = d.kind === 'leave' ? null : at
  if (d.kind !== 'down') return
  local.sparks = [...local.sparks, { ...at, age: 0 }]
  if (!local.sparkTimer) {
    local.sparkTimer = $.clock.every(100, () => {
      local.sparks = local.sparks.map(p => ({ ...p, age: p.age + 1 })).filter(p => p.age < 7)
      if (local.sparks.length === 0) {
        local.sparkTimer?.cancel()
        local.sparkTimer = null
      }
      void repaint($)
    })
  }
  await repaint($)
}

async function measure($: EngineInterface) {
  const usage = await $.session.usage({ breakdown: 'summary' })
  const tokens = usage.context.tokens
  if (tokens === undefined) return
  const limit = usage.context.breakdown?.autoCompactThreshold ?? usage.context.window
  // Growth counts the conversation alone: everything but the Messages row is
  // fixed overhead (system prompt, tools, memory). Where no such row is
  // listed, the lowest context seen this session stands in, kept in session
  // state so a reload of the mod does not restart the growth.
  const rows = usage.context.breakdown
  const messages = rows?.categories.find(c => c.kind === 'used' && /message/i.test(c.name))
  const lowest = await update($, baseline, b => Math.min(b ?? tokens, tokens))
  const base = rows && messages ? Math.max(0, rows.totalTokens - messages.tokens) : (lowest ?? tokens)
  const linear = Math.max(0, Math.min(1, (tokens - base) / Math.max(1, limit - base)))
  // a square root, so the first stretch of a long window still shows growth
  const next = Math.round(Math.sqrt(linear) * 1000) / 1000
  await update($, fill, () => next)
}

function openPane($: EngineInterface): Promise<UiOpenResult> {
  return $.ui.open({ id: PANE, title: 'Forest' })
}

async function animate($: EngineInterface) {
  local.tick += 1
  for (const [id, size] of local.mounted) {
    const scene = await sceneFor($, size.columns, size.rows)
    const r = await $.ui.blit({ requestId: id, key: 'scene', cells: encode(scene.cells), ...size }).catch(() => null)
    if (!r || 'deny' in r) local.mounted.delete(id)
  }
}

/** A small stable number from a string, so each session draws its own scene. */
function seedFrom(text: string) {
  let h = 2166136261
  for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 16777619)
  return (h >>> 0) % 100000
}

async function describeScene($: EngineInterface) {
  const m = moodOf((await read($, seed)) ?? 7)
  const animals = [...new Set(m.cast)].join(', ')
  return `${m.season}, ${Math.round(m.pines * 100)}% pines, ${animals}`
}

const isStyle = (s: unknown): s is Style => s === 'ascii' || s === 'soft' || s === 'painted'

async function speed($: EngineInterface) {
  const kept = Number(await $.store.get('speed').catch(() => undefined))
  return Number.isFinite(kept) && kept >= 0 ? kept : DEFAULT_SPEED
}

/** (Re)starts the animation at the kept speed; 0 holds the scene still. */
async function startTimer($: EngineInterface) {
  local.timer?.cancel()
  local.timer = null
  const seconds = await speed($)
  if (seconds > 0) local.timer = $.clock.every(Math.round(seconds * 1000), () => void animate($))
}

async function readHost($: EngineInterface) {
  const rows = await $.config.list().catch(() => [])
  const t = rows.find(row => row.key === 'theme')?.value
  local.theme = typeof t === 'string' && t.includes('light') ? 'light' : 'dark'
  // the module's clock may run in UTC: ask the host for its offset
  const out = await $.process.run(['date', '+%z']).catch(() => null)
  const m = out?.stdout.trim().match(/^([+-])(\d\d)(\d\d)$/)
  if (m) local.utcOffsetHours = (m[1] === '-' ? -1 : 1) * (Number(m[2]) + Number(m[3]) / 60)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'forest',
      description: 'Open the forest; style ascii|soft|painted, set <0-100> to fast-forward growth, <0-100> to preview it, reseed, hour <h>, speed <seconds>, live',
      argumentHint: '[style <s>|set <n>|<n>|reseed|hour <h>|speed <s>|live]',
    })
    await readHost($)
    const kept = await $.store.get('style').catch(() => undefined)
    if (isStyle(kept)) await update($, style, () => kept)
    // the scene's character follows the session; a reload keeps the one in state
    if ((await read($, seed)) === null) {
      const id = await $.session.id().catch(async () => String(await $.clock.now()))
      await update($, seed, () => seedFrom(id))
    }
    await measure($).catch(() => {})
    void openPane($)
    await startTimer($)

    return next(e)
  })

  on('ui.message', async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    await onPointer($, e.data)
    return {}
  })

  on('session.measure', async ($, e, next) => {
    await measure($).catch(() => {})
    return next(e)
  })

  on('command.run', { command: 'forest' }, async ($, e) => {
    const [first, second] = (e.args ?? '').trim().toLowerCase().split(/\s+/).filter(Boolean)
    if (first === 'style') {
      if (!isStyle(second)) {
        return { text: `Forest: drawn in ${await read($, style)}. Choose with /forest style ascii|soft|painted.` }
      }
      await $.store.set('style', second)
      await update($, style, () => second)
      await openPane($)
      return { text: `Forest: drawn in ${second}.` }
    }
    if (first === 'reseed') {
      const rolled = Math.floor(Math.random() * 100000)
      await update($, seed, () => rolled)
      await openPane($)
      return { text: `Forest: a new scene (${await describeScene($)}).` }
    }
    if (first === 'speed') {
      const seconds = Number(second)
      if (second === undefined || !Number.isFinite(seconds) || seconds < 0) {
        return { text: `Forest: animation steps every ${await speed($)}s. Set it with /forest speed <seconds>; 0 holds the scene still.` }
      }
      const kept = Math.min(600, Math.round(seconds * 10) / 10)
      await $.store.set('speed', kept)
      await startTimer($)
      return { text: kept === 0 ? 'Forest: the scene holds still.' : `Forest: animation steps every ${kept}s.` }
    }
    if (first === 'set' && second !== undefined && !Number.isNaN(Number(second))) {
      const target = clamp01(Number(second) / 100)
      await update($, preview, () => null)
      void fastForward($, target)
      await openPane($)
      return { text: `Forest: fast-forwarding to ${Math.round(target * 100)}%; it grows on from there with the conversation.` }
    } else if (first === 'live') {
      local.sweep?.cancel()
      local.sweep = null
      await update($, preview, () => null)
      await update($, hourOverride, () => null)
      await update($, boost, () => 0)
    } else if (first === 'hour' && second !== undefined && !Number.isNaN(Number(second))) {
      await update($, hourOverride, () => ((Number(second) % 24) + 24) % 24)
    } else if (first !== undefined && !Number.isNaN(Number(first))) {
      await update($, preview, () => Math.max(0, Math.min(100, Number(first))) / 100)
    }
    const opened = await openPane($)
    const growth = await shownFill($)
    const shown = opened.isPlaced ? 'shown' : `waiting (${opened.reason})`
    return { text: `Forest: ${shown}, growth ${Math.round(growth * 100)}%, ${await describeScene($)}.` }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
      const columns = Math.max(1, Math.min(512, e.props.bodyColumns))
      const rows = Math.max(1, Math.min(256, e.props.scroll.bodyRows))
      const scene = await sceneFor($, columns, rows)

      if (e.surface === 'terminal') {
        // the scene, with an invisible Client laid over it for the pointer
        const { Box, Client, Raster } = $.ui.resolve(e)
        local.mounted.set(PANE, { columns, rows })
        return (
          <Box width={columns} height={rows}>
            <Raster key="scene" columns={columns} rows={rows} cells={encode(scene.cells)} />
            <Box position="absolute" top={0} left={0} width={columns} height={rows}>
              <Client key="pointer" module="./pointer.tsx" width={columns} height={rows} />
            </Box>
          </Box>
        )
      }

      // surfaces without Raster: one Text per row, coloured runs inside
      const { Box, Text } = $.ui.resolve(e)
      const lines = textRows(scene, Text)
      return <Box flexDirection="column">{lines}</Box>
    })
}

