import type { ElementConstructor, RenderNode, TextProps } from 'claude-code'

import { DEFAULT, type Scene } from './scene'

const hex = (n: number) => '#' + n.toString(16).padStart(6, '0')

/** A scene as one Text per row, each holding runs of one colour: for surfaces without Raster. */
export function textRows(scene: Scene, Text: ElementConstructor<TextProps>): RenderNode[] {
  const { columns, rows, cells } = scene
  const lines: RenderNode[] = []
  for (let y = 0; y < rows; y++) {
    const runs: RenderNode[] = []
    let run = ''
    let color = -1
    const flush = () => {
      if (run) runs.push(color === DEFAULT ? <Text>{run}</Text> : <Text color={hex(color)}>{run}</Text>)
      run = ''
    }
    for (let x = 0; x < columns; x++) {
      const i = (y * columns + x) * 3
      const fg = cells[i] === 32 ? DEFAULT : cells[i + 1]!
      if (fg !== color) {
        flush()
        color = fg
      }
      run += String.fromCodePoint(cells[i]!)
    }
    flush()
    lines.push(<Text>{runs}</Text>)
  }
  return lines
}

