// A surface module laid invisibly over the scene: it draws nothing and hands
// the pointer to the hooks module, which owns the scene and repaints it.

import type { ClientModule } from 'claude-code'

const Pointer: ClientModule = (_props, surface) => {
  if (surface.state === undefined) {
    surface.setState(true)
    surface.onPointer(e => surface.post({ kind: e.type, x: e.x, y: e.y }))
  }
  const { Box } = surface.elements
  return <Box width={surface.columns || 1} height={surface.rows || 1} />
}

export default Pointer

