declare module 'claude-code' {
  interface PluginState {
    forest: {
      /** Growth from the live context, 0 to 1. */
      fill: number
      /** A fill set by `/forest <n>` that stands in for the live one. */
      preview: number | null
      /** An hour set by `/forest hour <h>` that stands in for the clock. */
      hour: number | null
      /** The drawing style; kept across sessions in the store, mirrored here so a change redraws. */
      style: 'ascii' | 'soft' | 'painted'
      /** The scene's seed: from the session id, or rolled by `/forest reseed`. */
      seed: number | null
      /** Growth `/forest set` added on top of the live fill, -1 to 1. */
      boost: number
      /** The lowest context seen this session, in tokens: growth counts from it. */
      baseline: number | null
    }
  }
}
